package cn.cloudcurtain.tv;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import java.util.*;import okhttp3.HttpUrl;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class BaiduStreamsTest {
 @Test public void streamRequestEscapesPathAndHasNoEntitlementOverrides()throws Exception{MediaSpec m=BaiduStreams.spec(new CloudApi.Entry("/电影/a&b #1.mkv","a.mkv",false,123),1080);HttpUrl url=HttpUrl.get(m.url);assertEquals("/电影/a&b #1.mkv",url.queryParameter("path"));assertNull(url.queryParameter("vip"));assertNull(url.queryParameter("adToken"));assertNull(m.headers.get("Cookie"));assertEquals("BAIDU:/电影/a&b #1.mkv",MediaSpec.parse(m.json()).key);assertEquals(123,MediaSpec.parse(m.json()).sourceBytes);assertTrue(m.compatible);}
 @Test public void missingOrInvalidManifestsDoNotBecomePlayableQualityOptions(){assertFalse(BaiduStreams.completeManifest("{\"errno\":31023}"));assertFalse(BaiduStreams.completeManifest("#EXTM3U\n#EXTINF:7,\nsegment.ts"));assertTrue(BaiduStreams.completeManifest("#EXTM3U\n#EXTINF:7,\nsegment.ts\n#EXT-X-ENDLIST\n"));}
 @Test public void selectsHighestAvailableStreamWithoutRetryingDeniedAccount()throws Exception{List<String> calls=new ArrayList<>();CloudApi.Entry entry=new CloudApi.Entry("/a.mkv","a.mkv",false,1);MediaSpec result=BaiduStreams.highest(entry,m->{calls.add(m.quality);return m.quality.equals("baidu:720");});assertEquals("baidu:720",result.quality);assertEquals(Arrays.asList("baidu:1080","baidu:720"),calls);calls.clear();try{BaiduStreams.highest(entry,m->{calls.add(m.quality);throw new Net.ServiceException(403,"");});fail();}catch(Net.ServiceException expected){assertEquals(1,calls.size());}}
 @Test public void baiduCanRecoverOneExpiredAddressAndOneUnsupportedOriginal(){PlaybackRecovery r=new PlaybackRecovery("BAIDU");assertTrue(r.error(null,androidx.media3.common.PlaybackException.ERROR_CODE_DECODING_FORMAT_UNSUPPORTED,false));assertFalse(r.error(null,androidx.media3.common.PlaybackException.ERROR_CODE_DECODING_FORMAT_UNSUPPORTED,false));assertTrue(r.stalled(45000,false,false));assertFalse(r.stalled(90000,false,false));}
}
